(function(root){
  'use strict';
  const T=root.AstrisTransport,L=root.AstrisLeadtime,S=root.AstrisSensors;
  const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const num=(v,n=2)=>Number.isFinite(v)?v.toLocaleString('uk-UA',{maximumFractionDigits:n}):'—';
  const time=v=>Number.isFinite(v)?new Date(v).toISOString().slice(11,19):'—';
  const kpi=(label,value,note='')=>'<article class="panel verification-kpi"><span>'+label+'</span><strong>'+value+'</strong>'+(note?'<small>'+note+'</small>':'')+'</article>';
  const table=(head,rows)=>'<div class="verification-scroll"><table class="verification-table"><thead><tr>'+head.map(h=>'<th scope="col">'+h+'</th>').join('')+'</tr></thead><tbody>'+rows+'</tbody></table></div>';
  const fold=(id,title,body)=>'<details class="panel verification-section compact-details" data-persist="'+id+'"><summary>'+title+'</summary>'+body+'</details>';
  function delivery(s,id){
    const q=T.summary(s,id),c=q.config;
    const form='<form id="transport-form" class="verification-form"><label class="field">Затримка, хв<input name="delayMinutes" type="number" min="0" max="30" step="0.5" value="'+c.delayMinutes+'" required></label><label class="field">Додаткова затримка до, хв<input name="variationMinutes" type="number" min="0" max="10" step="0.5" value="'+c.variationMinutes+'" required></label><label class="field">Втрачати кожен N-й пакет<input name="dropEvery" type="number" min="0" max="20" step="1" value="'+c.dropEvery+'" required><small>0 — без втрат; інакше від 2 до 20</small></label><button class="button primary" type="submit">Зберегти</button><p id="transport-error" class="form-error" role="alert"></p></form><p>Зміни діють на нові відправлення. Пакети в черзі залишаються. Додаткова затримка повторює N, 0, N/2 хв; доставка відбувається щохвилини симуляції.</p>';
    return '<div class="verification-kpis">'+kpi('Середня затримка',num(q.meanDelay)+' хв','Останні '+q.latencies.length+' отриманих пакетів')+kpi('У черзі',q.pending)+kpi('Втрачено',q.dropped+' / '+q.sent,num(q.dropPercent)+'% надісланих')+kpi('Поза порядком',q.reordered,q.stale+' застарілих при отриманні')+'</div><section class="panel verification-section"><h2>Режим доставки</h2><div class="verification-presets"><button class="button" data-action="transport-preset" data-preset="direct">Без затримки</button><button class="button" data-action="transport-preset" data-preset="delay">Затримка 4 хв</button><button class="button" data-action="transport-preset" data-preset="reorder">Не за порядком</button><button class="button" data-action="transport-preset" data-preset="loss">Втрати 20%</button></div><p>Зараз: затримка '+c.delayMinutes+' хв'+(c.variationMinutes?', додатково до '+c.variationMinutes+' хв':'')+(c.dropEvery?', втрата кожного '+c.dropEvery+'-го пакета':'')+'.</p></section>'+fold('delivery-settings','Власні параметри',form)+'<section class="panel verification-section"><h2>Останні пакети · UTC</h2>'+table(['Пакет','Виміряно','Надіслано','Отримано','Затримка','Стан'],q.records.length?q.records.slice(0,8).map(r=>'<tr><td>#'+r.id+'</td><td>'+time(r.measuredAt)+'</td><td>'+time(r.sentAt)+'</td><td>'+time(r.receivedAt)+'</td><td>'+num(r.latencyMinutes)+' хв</td><td>'+esc(r.status==='dropped'?'Втрачено':r.reordered?'Додано в історію':r.stale?'Застарілий':r.duplicate?'Повтор':'Отримано')+'</td></tr>').join(''):'<tr><td colspan="6">Натисніть «+1 хв», щоб отримати нові пакети.</td></tr>')+'</section>';
  }
  const statuses={pending:'Очікує факту',confirmed:'Підтверджено','not-confirmed':'Не підтвердилось',unverified:'Бракує даних',cancelled:'Скасовано'};
  function leadtime(s,id,key){
    const q=L.summary(s,id,key),c=S.get(s,key);
    const rows=q.warnings.length?q.warnings.slice(0,12).map(w=>'<tr><td>'+time(w.issuedAt)+'<small>'+esc(w.model)+'</small></td><td>'+time(w.predictedCrossAt)+'</td><td>'+time(w.actualTs)+'</td><td>'+num(w.leadMinutes)+' хв</td><td>'+statuses[w.status]+(w.status==='pending'&&s.now>=w.expiresAt?'<small>Вікно минуло; нових даних ще немає</small>':'')+(w.reason?'<small>'+esc(w.reason)+'</small>':'')+'</td></tr>').join(''):'<tr><td colspan="5">Задайте межу показника. Попередження перевірятимуться за наступними вимірюваннями.</td></tr>';
    const explanation='<code class="rule-equation">Завчасність = (час виміряного перетину − час видачі попередження) / 60 000</code><p>Додатне число — попередили раніше події. Нуль або від’ємне — завчасності немає. Час пізнього отримання пакета не додає випередження.</p><p>Перетин фіксується за двома послідовними валідними вимірюваннями. Якщо даних бракує, результат не рахується хибним або успішним. Зміна параметрів скасовує незавершені перевірки.</p>';
    const events=table(['Виміряно','Отримано','Значення / межа','Попередили завчасно'],q.events.length?q.events.slice(0,10).map(e=>'<tr><td>'+time(e.ts)+'</td><td>'+time(e.detectedAt)+'</td><td>'+num(e.value)+' / '+num(e.bound)+' '+esc(c.unit)+'</td><td>'+(e.timelyWarning?'Так':'Ні')+'</td></tr>').join(''):'<tr><td colspan="4">Перетинів із достатніми даними ще немає.</td></tr>');
    return '<div class="verification-kpis">'+kpi('Середнє випередження',num(q.meanLead)+' хв',q.confirmed+' підтверджених')+kpi('Очікують факту',q.pending,q.unverified+' із неповними даними')+kpi('Не підтвердились',q.notConfirmed)+kpi('Без завчасного сигналу',q.withoutTimelyWarning,'Із '+q.events.length+' спостережених перетинів')+'</div><section class="panel verification-section"><div class="verification-heading"><div><h2>Попередження · UTC</h2><p>'+esc(S.limitsText(s,key))+' · прогноз '+c.forecastMinutes+' хв</p></div><button class="button" data-action="settings" data-metric="'+key+'">Задати межі</button></div>'+table(['Видано','Прогноз перетину','Факт перетину','Випередження','Результат'],rows)+'</section>'+fold('lead-formula','Як рахується випередження',explanation)+fold('lead-events','Спостережені перетини',events);
  }
  function control(s,busy,progress){
    const report=s.controlEvaluation;
    const intro='<section class="panel verification-section"><div class="verification-heading"><div><h2>Перевірка прогнозу</h2><p>6 змодельованих рядів · 72 початкові та 48 контрольних точок · горизонти 1, 5 і 10 хв</p></div><button class="button primary" data-action="run-control" '+(busy?'disabled':'')+'>'+(busy?'Рахуємо '+progress:'Запустити перевірку')+'</button></div><p>Окремий тестовий набір. Значення в умовних одиницях; це не перевірка на реальних медичних даних.</p></section>';
    if(!report)return intro;
    const rows=report.aggregate.map(r=>'<tr><td>+'+r.horizon+' хв</td><td>'+r.n+'</td><td>'+num(r.mae,3)+'</td><td>'+num(r.rmse,3)+'</td><td>'+num(r.naiveRmse,3)+'</td><td>'+num(r.coverage,1)+'%<small>Із '+r.intervalN+' доступних діапазонів</small></td></tr>').join('');
    const cases=table(['Ряд','Горизонт','n / пропусків','MAE','RMSE','Базовий RMSE'],report.cases.flatMap(c=>c.byHorizon.map(r=>'<tr><td>'+esc(c.name)+'</td><td>+'+r.horizon+' хв</td><td>'+r.n+' / '+r.skipped.length+'</td><td>'+num(r.mae,3)+'</td><td>'+num(r.rmse,3)+'</td><td>'+num(r.naiveRmse,3)+'</td></tr>')).join(''));
    const a=report.anomalies,anomalies='<p>У контрольних 48 точках одного ряду навмисно додано 3 викиди. Правило |z| ≥ 3 використовує базу з перших 30 точок.</p>'+table(['Виявлено · TP','Хибні сигнали · FP','Пропущено · FN','Без сигналу · TN'],'<tr><td>'+a.tp+'</td><td>'+a.fp+'</td><td>'+a.fn+'</td><td>'+a.tn+'</td></tr>')+'<p>Precision: '+num(a.precision===null?null:a.precision*100,1)+'%; recall: '+num(a.recall===null?null:a.recall*100,1)+'%. Результат стосується лише внесених викидів.</p>';
    const method='<p>Рівень із шумом, дрейф, коливання, зміна режиму, викиди та пропуски. Кожен прогноз використовує лише вже відомі значення. Параметри фіксовані; майбутні значення та мітки викидів до моделі не потрапляють.</p><p>MAE — середня абсолютна помилка. RMSE сильніше враховує великі помилки. Базовий прогноз повторює останнє значення й оцінюється на тих самих цілях.</p><p>Покриття — частка фактів усередині доступних діапазонів. Воно не гарантує такої самої точності надалі.</p><p>Набір '+esc(report.version)+'; seed 91001–91006. Дані й окремі прогнози входять до збереженої сесії.</p>';
    return intro+'<section class="panel verification-section"><h2>Помилка прогнозу</h2>'+table(['Горизонт','Прогнозів','MAE','RMSE','Базовий RMSE','Покриття'],rows)+'<p>Менша помилка — кращий результат. Базовий прогноз повторює останнє значення.</p></section>'+fold('control-cases','Результати окремих рядів',cases)+fold('control-anomalies','Перевірка виявлення викидів',anomalies)+fold('control-method','Умови перевірки та формули',method);
  }
  function section(s,id,tab,key,busy,progress){return tab==='delivery'?delivery(s,id):tab==='leadtime'?leadtime(s,id,key):control(s,busy,progress);}
  root.AstrisVerification={section};
})(globalThis);
